/** The brand colour for a logo on Hub's dark background: very dark brand colours (Next.js, Express, Expo) use the text colour instead. */
export function logoColor(hex: string): string {
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b < 0.18 ? "var(--text-2)" : "#" + hex;
}
